import sys

MOD = 998244353
G = 3

def ntt(a, invert):
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(G, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for i in range(start, end):
                u = a[i]
                v = a[i + half] * w % MOD
                a[i] = (u + v) % MOD
                a[i + half] = (u - v) % MOD
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD

def convolution(a, b):
    need = len(a) + len(b) - 1
    if min(len(a), len(b)) <= 40:
        res = [0] * need
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    res[i + j] = (res[i + j] + x * y) % MOD
        return res

    n = 1
    while n < need:
        n <<= 1
    fa = a + [0] * (n - len(a))
    fb = b + [0] * (n - len(b))
    ntt(fa, False)
    ntt(fb, False)
    for i in range(n):
        fa[i] = fa[i] * fb[i] % MOD
    ntt(fa, True)
    return fa[:need]

def main():
    input = sys.stdin.readline
    N = int(input())
    S = input().strip()

    if S[0] != 'B' or S[-1] != 'W':
        print(0)
        return

    fact = [1] * (N + 1)
    invfact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact[N] = pow(fact[N], MOD - 2, MOD)
    for i in range(N, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    # For every number y of already seen W's, let x be the number of B's
    # before that W.  Events with equal x are nested, so retain only the last.
    last_y_for_x = {}
    bcnt = 0
    wcnt = 0
    for ch in S:
        if ch == 'B':
            bcnt += 1
        else:
            wcnt += 1
            if wcnt == N:
                break
            x = bcnt
            y = wcnt
            if x == 0:
                print(0)
                return
            if x <= y:
                last_y_for_x[x] = y

    # Points are (y, x), sorted by y. Add a terminal point (N, N).
    points = [(0, 0)]
    for x, y in last_y_for_x.items():
        points.append((y, x))
    points.sort()
    points.append((N, N))

    m = len(points)
    ys = [p[0] for p in points]
    xs = [p[1] for p in points]

    val = [0] * m
    acc = [0] * m
    val[0] = 1
    terminal = m - 1

    def solve(l, r):
        if l == r:
            if l == 0:
                return
            if l == terminal:
                val[l] = acc[l] % MOD
            else:
                gap = ys[l] - xs[l]
                val[l] = (-acc[l] * invfact[gap]) % MOD
            return

        mid = (l + r) >> 1
        solve(l, mid)

        left_count = mid - l + 1
        right_count = r - mid

        # Direct computation for small rectangles.
        if left_count * right_count <= 7000:
            for j in range(mid + 1, r + 1):
                y = ys[j]
                total = 0
                for i in range(l, mid + 1):
                    total += val[i] * fact[y - xs[i]]
                acc[j] = (acc[j] + total) % MOD
        else:
            xmin = xs[l]
            xmax = xs[mid]
            ymax = ys[r]

            a = [0] * (xmax - xmin + 1)
            for i in range(l, mid + 1):
                a[xs[i] - xmin] = (a[xs[i] - xmin] + val[i]) % MOD

            b = [0] * (ymax - xmin + 1)
            for k in range(len(b)):
                b[k] = fact[k]

            c = convolution(a, b)
            for j in range(mid + 1, r + 1):
                idx = ys[j] - xmin
                if idx < len(c):
                    acc[j] = (acc[j] + c[idx]) % MOD

        solve(mid + 1, r)

    solve(0, m - 1)
    print(val[terminal] % MOD)

