class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        children = [{}]
        count = [0]
        depth = [0]

        for word in words:
            node = 0
            for ch in word:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    count.append(0)
                    depth.append(depth[node] + 1)
                node = nxt
                count[node] += 1

        max_depth = max(depth)
        qualified_at_depth = [0] * (max_depth + 1)

        for node in range(1, len(children)):
            if count[node] >= k:
                qualified_at_depth[depth[node]] += 1

        candidate_depths = [
            d for d in range(max_depth, 0, -1)
            if qualified_at_depth[d] > 0
        ]

        answer = [0] * n

        for i, word in enumerate(words):
            bad_depths = set()
            node = 0

            for ch in word:
                node = children[node][ch]
                d = depth[node]
                if count[node] == k and qualified_at_depth[d] == 1:
                    bad_depths.add(d)

            for d in candidate_depths:
                if d not in bad_depths:
                    answer[i] = d
                    break

        return answer

