class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        self.g[fr].append([to, cap, len(self.g[to])])
        self.g[to].append([fr, 0, len(self.g[fr]) - 1])

    def max_flow(self, s, t):
        flow = 0
        INF = 10**18

        while True:
            level = [-1] * self.n
            q = deque([s])
            level[s] = 0

            while q:
                v = q.popleft()
                for to, cap, _ in self.g[v]:
                    if cap > 0 and level[to] < 0:
                        level[to] = level[v] + 1
                        q.append(to)

            if level[t] < 0:
                return flow

            it = [0] * self.n

            def dfs(v, f):
                if v == t:
                    return f
                while it[v] < len(self.g[v]):
                    e = self.g[v][it[v]]
                    to, cap, rev = e
                    if cap > 0 and level[v] < level[to]:
                        d = dfs(to, min(f, cap))
                        if d:
                            e[1] -= d
                            self.g[to][rev][1] += d
                            return d
                    it[v] += 1
                return 0

            while True:
                f = dfs(s, INF)
                if f == 0:
                    break
                flow += f


def main():
    input = sys.stdin.readline
    N, M, K = map(int, input().split())
    edges = []
    for _ in range(M):
        u, v = map(int, input().split())
        edges.append((u - 1, v - 1))

    INF = 10**9

    def feasible(D):
        def node(v, level):
            return v * D + (level - 1)

        S = N * D
        T = S + 1
        dinic = Dinic(T + 1)

        # Vertex labels are nested:
        # label(v) >= i+1 => label(v) >= i
        for v in range(N):
            for i in range(2, D + 1):
                dinic.add_edge(node(v, i), node(v, i - 1), INF)

        # Vertex 1 has label 0, vertex N has label D.
        for i in range(1, D + 1):
            dinic.add_edge(node(0, i), T, INF)
            dinic.add_edge(S, node(N - 1, i), INF)

        for u, v in edges:
            for i in range(1, D + 1):
                # Pay 1 if label(v) >= i but label(u) < i.
                dinic.add_edge(node(v, i), node(u, i), 1)

            # An edge may increase labels by at most 1.
            for i in range(1, D):
                dinic.add_edge(node(v, i + 1), node(u, i), INF)

        return dinic.max_flow(S, T) <= K

    ans = 0
    for d in range(1, N):
        if feasible(d):
            ans = d

    print(ans)

