class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]

        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, idx))

        gains = [0] * len(conflictingPairs)

        largest = 0
        second_largest = 0
        largest_id = -1
        base_count = 0

        for right in range(1, n + 1):
            for left, pair_id in buckets[right]:
                if left > largest:
                    second_largest = largest
                    largest = left
                    largest_id = pair_id
                elif left > second_largest:
                    second_largest = left

            base_count += right - largest

            if largest_id != -1:
                gains[largest_id] += largest - second_largest

        return base_count + max(gains)

