class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        total_len = n + m - 1

        fixed = [None] * total_len

        # Apply all T constraints.
        for i, flag in enumerate(str1):
            if flag == 'T':
                for j, ch in enumerate(str2):
                    pos = i + j
                    if fixed[pos] is not None and fixed[pos] != ch:
                        return ""
                    fixed[pos] = ch

        # groups[pos] contains F-start indices whose last free position is pos.
        groups = [[] for _ in range(total_len)]

        for i, flag in enumerate(str1):
            if flag != 'F':
                continue

            last_free = -1
            already_different = False

            for j, ch in enumerate(str2):
                pos = i + j
                if fixed[pos] is None:
                    last_free = pos
                elif fixed[pos] != ch:
                    already_different = True
                    break

            # A fixed mismatch already guarantees this F condition.
            if already_different:
                continue

            # Entire substring is fixed and equal to str2.
            if last_free == -1:
                return ""

            groups[last_free].append(i)

        ans = fixed[:]
        alphabet = "abcdefghijklmnopqrstuvwxyz"

        # Fill free positions greedily from left to right.
        for pos in range(total_len):
            if ans[pos] is not None:
                continue

            forbidden = set()

            # For each F constraint whose final free position is here,
            # determine whether this position must differ from str2.
            for start in groups[pos]:
                matches_so_far = True

                for j, ch in enumerate(str2):
                    idx = start + j
                    if idx == pos:
                        continue
                    if ans[idx] != ch:
                        matches_so_far = False
                        break

                if matches_so_far:
                    forbidden.add(str2[pos - start])

            chosen = None
            for ch in alphabet:
                if ch not in forbidden:
                    chosen = ch
                    break

            if chosen is None:
                return ""

            ans[pos] = chosen

        return "".join(ans)

