                    continue

                parity = x % 2
                if required_parity is not None and parity != required_parity:
                    continue

                new_odd = odd_left - (parity == 1)
                new_even = even_left - (parity == 0)

                if new_odd + new_even == 0:
                    ways = 1
                else:
                    ways = count_completions(new_odd, new_even, 1 - parity)

                if k > ways:
                    k -= ways
                else:
                    answer.append(x)
                    used[x] = True
                    odd_left = new_odd
                    even_left = new_even
                    required_parity = 1 - parity
                    chosen = True
                    break

            if not chosen:
                return []

        return answer

