class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        perimeter = 4 * side

        def perimeter_pos(x: int, y: int) -> int:
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 3 * side - x
            return 4 * side - y

        positions = sorted(perimeter_pos(x, y) for x, y in points)
        n = len(positions)

        def feasible(dist: int) -> bool:
            extended = positions + [p + perimeter for p in positions]
            m = 2 * n
            nxt = [m] * m

            ptr = 0
            for i in range(m):
                if ptr < i + 1:
                    ptr = i + 1
                target = extended[i] + dist
                while ptr < m and extended[ptr] < target:
                    ptr += 1
                nxt[i] = ptr

            for start in range(n):
                cur = start
                limit = start + n

                for _ in range(k - 1):
                    cur = nxt[cur]
                    if cur >= limit:
                        break

                if cur < limit and extended[cur] - extended[start] <= perimeter - dist:
                    return True

            return False

        low, high = 0, side + 1

        while low + 1 < high:
            mid = (low + high) // 2
            if feasible(mid):
                low = mid
            else:
                high = mid

        return low

