    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(pattern: str):
            m = len(pattern)
            if m == 0:
                return list(range(n + 1))

            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and pattern[i] != pattern[j]:
                    j = pi[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                pi[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != pattern[j]:
                    j = pi[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]

            return result

        occ_a = occurrences(a)
        occ_b = occurrences(b)
        occ_c = occurrences(c)

        len_a = len(a)
        len_b = len(b)
        len_c = len(c)

        answer = float('inf')
        ia = 0
        ic = 0
        best_a_start = None

        for b_start in occ_b:
            while ia < len(occ_a) and occ_a[ia] + len_a <= b_start:
                best_a_start = occ_a[ia]
                ia += 1

            if best_a_start is None:
