class Solution:
    def countSubstrings(self, s: str) -> int:
        # dp[d][r] = number of substrings ending at the previous position
        # whose value has remainder r modulo d.
        dp = [None] + [[0] * d for d in range(1, 10)]
        ans = 0

        for ch in s:
            digit = ord(ch) - ord('0')

            for d in range(1, 10):
                old = dp[d]
                nxt = [0] * d

                for r, count in enumerate(old):
                    nxt[(r * 10 + digit) % d] += count

                # The substring consisting only of the current digit.
                nxt[digit % d] += 1
                dp[d] = nxt

            if digit != 0:
                ans += dp[digit][0]

        return ans

