class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            if target == 0:
                return True

            moves = 1  # First move: -1 -> 0
            current_visits = 1

            for i in range(n - 1):
                required = (target + points[i] - 1) // points[i]
                extra = max(0, required - current_visits)

                if i == n - 2:
                    last_required = (target + points[i + 1] - 1) // points[i + 1]

                    # End at index n - 2 after bouncing with the last index.
                    if extra >= last_required:
                        if moves + 2 * extra <= m:
                            return True

                    # Move to the last index, then bounce if it still needs visits.
                    cost = moves + 2 * extra + 1
                    last_visits = extra + 1
                    if last_visits < last_required:
                        cost += 2 * (last_required - last_visits)

                    return cost <= m

                moves += 2 * extra + 1
                if moves > m:
                    return False

                current_visits = extra + 1

            return False

        low = 0
        high = min(points) * m + 1

        while low + 1 < high:
            mid = (low + high) // 2
            if can(mid):
                low = mid
            else:
                high = mid

        return low

