class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)

        def count_subarrays(left: int, right: int) -> int:
            left = min(left, k)
            right = min(right, k)

            full_rows = min(left, k - right + 1)
            result = full_rows * right

            remaining = left - full_rows
            if remaining > 0:
                first = k - full_rows
                last = k - left + 1
                result += remaining * (first + last) // 2

            return result

        def contribution_for_minimum() -> int:
            prev = [-1] * n
            nxt = [n] * n
            stack = []

            # Previous strictly smaller
            for i in range(n):
                while stack and nums[stack[-1]] >= nums[i]:
                    stack.pop()
                if stack:
                    prev[i] = stack[-1]
                stack.append(i)

            stack.clear()

            # Next smaller or equal
            for i in range(n - 1, -1, -1):
                while stack and nums[stack[-1]] > nums[i]:
                    stack.pop()
                if stack:
                    nxt[i] = stack[-1]
                stack.append(i)

            total = 0
            for i, value in enumerate(nums):
                left = i - prev[i]
                right = nxt[i] - i
                total += value * count_subarrays(left, right)

            return total

        def contribution_for_maximum() -> int:
            prev = [-1] * n
            nxt = [n] * n
            stack = []

            # Previous strictly greater
            for i in range(n):
                while stack and nums[stack[-1]] <= nums[i]:
                    stack.pop()
                if stack:
                    prev[i] = stack[-1]
                stack.append(i)

            stack.clear()

            # Next greater or equal
            for i in range(n - 1, -1, -1):
                while stack and nums[stack[-1]] < nums[i]:
                    stack.pop()
                if stack:
                    nxt[i] = stack[-1]
                stack.append(i)

            total = 0
            for i, value in enumerate(nums):
                left = i - prev[i]
                right = nxt[i] - i
                total += value * count_subarrays(left, right)

            return total

        return contribution_for_minimum() + contribution_for_maximum()

class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        total_cells = m * n

        fact = [1] * (total_cells + 1)
        for i in range(1, total_cells + 1):
            fact[i] = fact[i - 1] * i % MOD

        inv_fact = [1] * (total_cells + 1)
        inv_fact[total_cells] = pow(fact[total_cells], MOD - 2, MOD)
        for i in range(total_cells, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        def comb(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

        row_distances = m * (m - 1) * (m + 1) // 6
        col_distances = n * (n - 1) * (n + 1) // 6

        total_pair_distance = (
            row_distances * n * n +
            col_distances * m * m
        ) % MOD

        arrangements_per_pair = comb(total_cells - 2, k - 2)

        return total_pair_distance * arrangements_per_pair % MOD

