class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        negatives = sorted(set(x for x in nums if x < 0))
        index = {x: i for i, x in enumerate(negatives)}
        m = len(negatives)

        # Standard Kadane result: covers doing no operation.
        cur = best = nums[0]
        for x in nums[1:]:
            cur = max(x, cur + x)
            best = max(best, cur)

        if m == 0:
            return best

        INF = 10**30
        size = 4 * m
        mn = [0] * size
        smn = [INF] * size
        mx = [0] * size
        lazy_add = [0] * size

        def apply_add(node: int, value: int) -> None:
            mn[node] += value
            if smn[node] < INF:
                smn[node] += value
            mx[node] += value
            lazy_add[node] += value

        def apply_chmax(node: int, value: int) -> None:
            if mn[node] >= value:
                return
            if mx[node] == mn[node]:
                mx[node] = value
            mn[node] = value

        def push(node: int) -> None:
            if lazy_add[node]:
                apply_add(node * 2, lazy_add[node])
                apply_add(node * 2 + 1, lazy_add[node])
                lazy_add[node] = 0

            bound = mn[node]
            if mn[node * 2] < bound:
                apply_chmax(node * 2, bound)
            if mn[node * 2 + 1] < bound:
                apply_chmax(node * 2 + 1, bound)

        def pull(node: int) -> None:
            left = node * 2
            right = left + 1

            mx[node] = max(mx[left], mx[right])

            if mn[left] < mn[right]:
                mn[node] = mn[left]
                smn[node] = min(smn[left], mn[right])
            elif mn[left] > mn[right]:
                mn[node] = mn[right]
                smn[node] = min(mn[left], smn[right])
            else:
                mn[node] = mn[left]
                smn[node] = min(smn[left], smn[right])

        def range_chmax(node: int, l: int, r: int, value: int) -> None:
            if mn[node] >= value:
                return
            if smn[node] > value:
                apply_chmax(node, value)
                return

            push(node)
            mid = (l + r) // 2
            range_chmax(node * 2, l, mid, value)
            range_chmax(node * 2 + 1, mid + 1, r, value)
            pull(node)

        def point_get(node: int, l: int, r: int, pos: int) -> int:
            if l == r:
                return mn[node]
            push(node)
            mid = (l + r) // 2
            if pos <= mid:
                return point_get(node * 2, l, mid, pos)
            return point_get(node * 2 + 1, mid + 1, r, pos)

        def point_set(node: int, l: int, r: int, pos: int, value: int) -> None:
            if l == r:
                mn[node] = mx[node] = value
                smn[node] = INF
                lazy_add[node] = 0
                return

            push(node)
            mid = (l + r) // 2
            if pos <= mid:
                point_set(node * 2, l, mid, pos, value)
            else:
                point_set(node * 2 + 1, mid + 1, r, pos, value)
            pull(node)

        for value in nums:
            if value < 0:
                pos = index[value]
                old_value = point_get(1, 0, m - 1, pos)

                apply_add(1, value)
                range_chmax(1, 0, m - 1, 0)

                # Deleting this exact value means this occurrence contributes 0,
                # so its DP state must remain unchanged.
                point_set(1, 0, m - 1, pos, old_value)
            else:
                apply_add(1, value)

        # A positive value necessarily corresponds to a non-empty valid subarray
        # after deletion. Zero is already covered by ordinary Kadane when valid.
        if mx[1] > 0:
            best = max(best, mx[1])

        return best

class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        fact = [1] * n
        inv_fact = [1] * n

        for i in range(1, n):
            fact[i] = fact[i - 1] * i % MOD

        inv_fact[n - 1] = pow(fact[n - 1], MOD - 2, MOD)
        for i in range(n - 1, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        combinations = fact[n - 1] * inv_fact[k] % MOD * inv_fact[n - 1 - k] % MOD

        return combinations * m % MOD * pow(m - 1, n - 1 - k, MOD) % MOD

