    data = list(map(int, sys.stdin.buffer.read().split()))
    N, K = data[0], data[1]
    A = data[2:]

    total_xor = 0
    for x in A:
        total_xor ^= x

    r = min(K, N - K)

    if r == 0:
        print(total_xor)
        return

    use_complement = (K != r)
    best = 0

    if r == 1:
        if use_complement:
            for x in A:
                best = max(best, total_xor ^ x)
        else:
            best = max(A)
        print(best)
        return

    def dfs(start, need, current_xor):
        nonlocal best

        if need == 1:
            limit = N
            if use_complement:
                for i in range(start, limit):
                    best = max(best, total_xor ^ current_xor ^ A[i])
            else:
                for i in range(start, limit):
                    best = max(best, current_xor ^ A[i])
            return

        end = N - need + 1
        for i in range(start, end):
            dfs(i + 1, need - 1, current_xor ^ A[i])

    dfs(0, r, 0)
    print(best)

if __name__ == "__main__":
    main()

import sys

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())

    rows = {}

    for _ in range(M):
        x, y, c = input().split()
        x = int(x)
        y = int(y)

        if x not in rows:
            rows[x] = [0, N]  # minimum possible black length, maximum possible black length

        if c == 'B':
            rows[x][0] = max(rows[x][0], y)
        else:
            rows[x][1] = min(rows[x][1], y - 1)

    current = N

    for x in sorted(rows):
        low, high = rows[x]

        if low > high:
            print("No")
            return

        current = min(current, high)

        if current < low:
            print("No")
            return

    print("Yes")

