    main()

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)

        def can(limit: int) -> bool:
            if limit == 1:
                changes_start_0 = 0
                changes_start_1 = 0

                for i, ch in enumerate(s):
                    expected_0 = '0' if i % 2 == 0 else '1'
                    expected_1 = '1' if i % 2 == 0 else '0'

                    if ch != expected_0:
                        changes_start_0 += 1
                    if ch != expected_1:
                        changes_start_1 += 1

                return min(changes_start_0, changes_start_1) <= numOps

            operations = 0
            i = 0

            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1

                run_length = j - i
                operations += run_length // (limit + 1)

                if operations > numOps:
                    return False

                i = j

            return True

        left, right = 1, n

        while left < right:
            mid = (left + right) // 2

            if can(mid):
                right = mid
            else:
                left = mid + 1

        return left

