import heapq

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    H, W, X, P, Q = data[:5]
    values = data[5:]

    start = (P - 1) * W + (Q - 1)
    strength = values[start]

    visited = bytearray(H * W)
    visited[start] = 1
    heap = []

    def add_neighbor(idx):
        if not visited[idx]:
            visited[idx] = 1
            heapq.heappush(heap, (values[idx], idx))

    r, c = divmod(start, W)
    if r > 0:
        add_neighbor(start - W)
    if r + 1 < H:
        add_neighbor(start + W)
    if c > 0:
        add_neighbor(start - 1)
    if c + 1 < W:
        add_neighbor(start + 1)

    while heap:
        value, idx = heap[0]
        if value * X >= strength:
            break

        heapq.heappop(heap)
        strength += value

        r, c = divmod(idx, W)
        if r > 0:
            add_neighbor(idx - W)
        if r + 1 < H:
            add_neighbor(idx + W)
        if c > 0:
            add_neighbor(idx - 1)
        if c + 1 < W:
            add_neighbor(idx + 1)

    print(strength)

