import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    arr = data[1:]

    freq = {}
    total = 0
    mx = 0
    for a in arr:
        total += a
        if a > mx:
            mx = a
        freq[a] = freq.get(a, 0) + 1

    ans = (n + 1) * total

    m = 2
    limit = 2 * mx

    while m <= limit:
        mask = m - 1
        groups = {}

        for a, c in freq.items():
            r = a & mask
            v = groups.get(r)
            s = a * c
            if v is None:
                groups[r] = [c, s]
            else:
                v[0] += c
                v[1] += s

        subtract = 0
        for r, v in groups.items():
            q = (-r) & mask
            if r > q:
                continue

            w = groups.get(q)
            if w is None:
                continue

            c1, s1 = v
            if r == q:
                pair_sum = (c1 + 1) * s1
            else:
                c2, s2 = w
                pair_sum = s1 * c2 + s2 * c1

            subtract += pair_sum // m

        ans -= subtract
        m <<= 1

    print(ans)

