    main()

import sys

def solve():
    input = sys.stdin.buffer.readline
    n = int(input())
    a = list(map(int, input().split()))

    pref = [0] * (n + 1)
    for i, v in enumerate(a, 1):
        pref[i] = pref[i - 1] + v

    size = 1
    while size < n:
        size <<= 1

    NEG = -(10 ** 30)

    # Right expansion condition:
    # A[t] - pref[t-1] < -pref[l-1]
    d_tree = [NEG] * (2 * size)
    for i in range(n):
        d_tree[size + i] = a[i] - pref[i]
    for i in range(size - 1, 0, -1):
        d_tree[i] = max(d_tree[i << 1], d_tree[i << 1 | 1])

    # Left expansion condition:
    # A[t] + pref[t] < pref[r]
    e_tree = [NEG] * (2 * size)
    for i in range(n):
        e_tree[size + i] = a[i] + pref[i + 1]
    for i in range(size - 1, 0, -1):
        e_tree[i] = max(e_tree[i << 1], e_tree[i << 1 | 1])

    def first_ge(tree, left, x):
        """First index >= left with value >= x, or n."""
        if left >= n:
            return n

        l = left + size
        r = n + size
        right_nodes = []

        while l < r:
            if l & 1:
                if tree[l] >= x:
                    p = l
                    while p < size:
                        if tree[p << 1] >= x:
                            p <<= 1
                        else:
                            p = p << 1 | 1
                    return p - size
                l += 1
            if r & 1:
                r -= 1
                right_nodes.append(r)
            l >>= 1
            r >>= 1

        for node in reversed(right_nodes):
            if tree[node] >= x:
                p = node
                while p < size:
                    if tree[p << 1] >= x:
                        p <<= 1
                    else:
                        p = p << 1 | 1
                return p - size

        return n

    def last_ge(tree, right, x):
        """Last index <= right with value >= x, or -1."""
        if right < 0:
            return -1

        l = size
        r = right + 1 + size
        left_nodes = []

        while l < r:
            if l & 1:
                left_nodes.append(l)
                l += 1
            if r & 1:
                r -= 1
                if tree[r] >= x:
                    p = r
                    while p < size:
                        if tree[p << 1 | 1] >= x:
                            p = p << 1 | 1
                        else:
                            p <<= 1
                    return p - size
            l >>= 1
            r >>= 1

        for node in reversed(left_nodes):
            if tree[node] >= x:
                p = node
                while p < size:
                    if tree[p << 1 | 1] >= x:
                        p = p << 1 | 1
                    else:
                        p <<= 1
                return p - size

        return -1

    ans = [0] * n

    for k in range(n):
        # If neither initial neighbor is smaller, no move is possible.
        left_ok = (k > 0 and a[k - 1] < a[k])
        right_ok = (k + 1 < n and a[k + 1] < a[k])
        if not left_ok and not right_ok:
            ans[k] = a[k]
            continue

        l = k
        r = k

        while True:
            old_l = l
            old_r = r

            # Absorb as much as possible to the right.
            blocker = first_ge(d_tree, r + 1, -pref[l])
            r = blocker - 1

            # Absorb as much as possible to the left.
            blocker = last_ge(e_tree, l - 1, pref[r + 1])
            l = blocker + 1

            if l == old_l and r == old_r:
                break

        ans[k] = pref[r + 1] - pref[l]

    print(*ans)

if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        size = [1] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> bool:
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return False
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]
            return True

        owner = [-1] * (threshold + 1)
        components = n

        for i, value in enumerate(nums):
            if value > threshold:
                continue

            for multiple in range(value, threshold + 1, value):
                if owner[multiple] == -1:
                    owner[multiple] = i
                elif union(i, owner[multiple]):
                    components -= 1

        return components
